function showToast(text){let el=document.querySelector('#toast');el.textContent=text;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),1900)}
function startGame(){makeMaze();running=true;startedAt=performance.now();lastTime=startedAt;startScreen.classList.add('hidden');endScreen.classList.add('hidden');hud.style.opacity=1;touchControls.style.display=innerWidth<900?'block':'none';requestAnimationFrame(loop)}
function finish(won){running=false;document.querySelector('#end-tag').textContent=won?'Signal restored':'Vault sealed';document.querySelector('#end-title').innerHTML=won?'YOU\'RE<br>OUT.':'SIGNAL<br>LOST';document.querySelector('#end-copy').textContent=won?`The vault opens. You escaped in ${formatTime(elapsed)}. The night air is yours again.`:'The signal faded before you found the way out. The maze is ready for another run.';setTimeout(()=>endScreen.classList.remove('hidden'),450)}
function formatTime(s){let m=Math.floor(s/60),ss=Math.floor(s%60);return String(m).padStart(2,'0')+':'+String(ss).padStart(2,'0')}
function move(dt){let speed=2.2*dt,rot=1.8*dt;if(keys.ArrowLeft||keys.q)player.a-=rot;if(keys.ArrowRight||keys.e)player.a+=rot;let forward=(keys.w||keys.ArrowUp?1:0)-(keys.s||keys.ArrowDown?1:0),strafe=(keys.d?1:0)-(keys.a?1:0);if(forward||strafe){let mag=Math.hypot(forward,strafe);forward/=mag;strafe/=mag;let dx=(Math.cos(player.a)*forward-Math.sin(player.a)*strafe)*speed,dy=(Math.sin(player.a)*forward+Math.cos(player.a)*strafe)*speed;let r=.19;if(!wall(player.x+dx+r*Math.sign(dx),player.y))player.x+=dx;if(!wall(player.x,player.y+dy+r*Math.sign(dy)))player.y+=dy}
 for(let t of things){let dist=Math.hypot(player.x-t.x,player.y-t.y);if(t.type==='key'&&dist<.43){things=things.filter(o=>o!==t);found++;document.querySelectorAll('.key-dot')[found-1]?.classList.add('found');showToast(`Signal key ${found} / 3 recovered`);document.querySelector('#objective').textContent=found===3?'Reach the gold-lit exit':'Find the remaining signal keys';beep(540+found*160,.12)}}let exit=things.find(t=>t.type==='exit');if(exit&&Math.hypot(player.x-exit.x,player.y-exit.y)<.48){if(found===3){beep(880,.3);finish(true)}else if(Math.hypot(player.x-exit.x,player.y-exit.y)<.52)showToast(`Exit locked · ${3-found} key${found===2?'':'s'} missing`)}}
function loop(now){if(!running)return;let dt=Math.min(.05,(now-lastTime)/1000);lastTime=now;elapsed=(now-startedAt)/1000;document.querySelector('#timer').textContent=formatTime(elapsed);move(dt);draw();requestAnimationFrame(loop)}
function beep(freq,duration){try{let AC=window.AudioContext||window.webkitAudioContext;if(!window.audioCtx)window.audioCtx=new AC();let o=window.audioCtx.createOscillator(),g=window.audioCtx.createGain();o.frequency.value=freq;o.type='sine';g.gain.setValueAtTime(.035,window.audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(.001,window.audioCtx.currentTime+duration);o.connect(g);g.connect(window.audioCtx.destination);o.start();o.stop(window.audioCtx.currentTime+duration)}catch{}}
function interact(){if(!running)return;let exit=things.find(t=>t.type==='exit');if(exit&&Math.hypot(player.x-exit.x,player.y-exit.y)<1.7){if(found===3){finish(true)}else showToast(`Exit locked · collect ${3-found} more key${found===2?'':'s'}`)}else showToast('No signal nearby · follow the map')}
document.querySelector('#start-button').addEventListener('click',()=>{beep(440,.08);startGame()});document.querySelector('#restart-button').addEventListener('click',startGame);
addEventListener('keydown',e=>{let k=e.key.length===1?e.key.toLowerCase():e.key;if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' '].includes(k))e.preventDefault();keys[k]=true;if(k==='e'&&!e.repeat)interact()});addEventListener('keyup',e=>{let k=e.key.length===1?e.key.toLowerCase():e.key;keys[k]=false});addEventListener('blur',()=>keys={});
// Drag-to-turn works on touch and mouse without capturing the movement pad.
let dragX=null;canvas.addEventListener('pointerdown',e=>{if(!running)return;dragX=e.clientX;canvas.setPointerCapture(e.pointerId)});canvas.addEventListener('pointermove',e=>{if(dragX===null||!running)return;let dx=e.clientX-dragX;player.a+=dx*.006;dragX=e.clientX});canvas.addEventListener('pointerup',()=>dragX=null);canvas.addEventListener('pointercancel',()=>dragX=null);
document.querySelectorAll('.pad button').forEach(button=>{let k=button.dataset.key;button.addEventListener('pointerdown',e=>{e.preventDefault();keys[k]=true;button.setPointerCapture(e.pointerId)});let release=()=>keys[k]=false;button.addEventListener('pointerup',release);button.addEventListener('pointercancel',release);button.addEventListener('lostpointercapture',release)});document.querySelector('#touch-interact').addEventListener('pointerdown',e=>{e.preventDefault();interact()});
// First frame shows a quiet, atmospheric vault behind the title card.
makeMaze();draw();
})();
</script>
</body>
</html>

