+function rng(){seed=(seed*1664525+1013904223)>>>0;return seed/4294967296}
+function makeMaze(){seed=(Date.now()^Math.floor(Math.random()*1e9))>>>0;world=Array.from({length:MAP_SIZE},()=>Array(MAP_SIZE).fill(1));let stack=[[1,1]];world[1][1]=0;while(stack.length){let[x,y]=stack[stack.length-1],opts=[[x+2,y],[x-2,y],[x,y+2],[x,y-2]].filter(([nx,ny])=>nx>0&&ny>0&&nx<MAP_SIZE-1&&ny<MAP_SIZE-1&&world[ny][nx]===1);if(!opts.length){stack.pop();continue}let[nx,ny]=opts[Math.floor(rng()*opts.length)];world[(y+ny)/2][(x+nx)/2]=0;world[ny][nx]=0;stack.push([nx,ny])}for(let i=0;i<18;i++){let x=2+Math.floor(rng()*(MAP_SIZE-4)),y=2+Math.floor(rng()*(MAP_SIZE-4));if(world[y][x]===1&&((world[y][x-1]===0&&world[y][x+1]===0)||(world[y-1][x]===0&&world[y+1][x]===0)))world[y][x]=0}
